<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { useI18n } from 'vue-i18n'
import Button from 'primevue/button'; import DatePicker from 'primevue/datepicker'; import Dialog from 'primevue/dialog'; import InputText from 'primevue/inputtext'
import AsyncContent from '@/components/common/AsyncContent.vue'; import PageHeader from '@/components/common/PageHeader.vue'
import { useAsyncData } from '@/composables/useAsyncData'
import { buildCalendarDays, getCalendarEvents } from '@/services/workspace'

const { locale } = useI18n()
const dialogOpen = ref(false); const monthOffset = ref(0); const eventTitle = ref(''); const eventDate = ref<Date>()
const baseMonth = new Date(2026, 6, 1)
const monthDate = computed(() => new Date(baseMonth.getFullYear(), baseMonth.getMonth() + monthOffset.value, 1))
const monthLabel = computed(() => new Intl.DateTimeFormat(locale.value, { year: 'numeric', month: 'long' }).format(monthDate.value))
const { data: events, loading, error, load } = useAsyncData(getCalendarEvents)
const days = computed(() => buildCalendarDays(monthDate.value, events.value || []))
const upcoming = computed(() => (events.value || []).filter(event => event.isoDate.startsWith(`${monthDate.value.getFullYear()}-${String(monthDate.value.getMonth()+1).padStart(2,'0')}`)).sort((a,b)=>a.isoDate.localeCompare(b.isoDate)))
const saveEvent = () => { if(!eventTitle.value.trim() || !eventDate.value) return; const created={ id:Date.now(), isoDate:`${eventDate.value.getFullYear()}-${String(eventDate.value.getMonth()+1).padStart(2,'0')}-${String(eventDate.value.getDate()).padStart(2,'0')}`, time:eventDate.value.toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'}), title:eventTitle.value.trim(), color:'#4f6bed' }; events.value=[...(events.value||[]),created]; dialogOpen.value=false; eventTitle.value='' }
onMounted(load)
</script>

<template><PageHeader :title="$t('calendar.title')" :description="$t('calendar.description')"><template #actions><Button :label="$t('calendar.new')" icon="pi pi-plus" @click="dialogOpen=true" /></template></PageHeader><AsyncContent :loading="loading" :error="error" :empty="!events" @retry="load"><div class="grid gap-3 xl:grid-cols-[minmax(0,1fr)_300px]"><section class="workspace-panel"><div class="mb-4 flex items-center justify-between"><div><Button icon="pi pi-angle-left" text rounded :aria-label="$t('calendarNavigation.previous')" @click="monthOffset--" /><Button :label="$t('calendar.today')" text @click="monthOffset=0" /><Button icon="pi pi-angle-right" text rounded :aria-label="$t('calendarNavigation.next')" @click="monthOffset++" /></div><strong>{{ monthLabel }}</strong><Button icon="pi pi-ellipsis-h" text rounded :aria-label="$t('actions.more')" /></div><div class="grid grid-cols-7 border-l border-t border-surface"><div v-for="day in $t('calendar.weekdays').split(',')" :key="day" class="border-b border-r border-surface p-2 text-center text-xs text-muted-color">{{ day }}</div><button v-for="day in days" :key="day.isoDate" class="min-h-24 border-b border-r border-surface bg-transparent p-2 text-left" :class="{'opacity-35':!day.current}" :aria-label="day.isoDate"><span class="text-xs">{{ day.date }}</span><span v-for="event in day.events" :key="event.id" class="mt-2 block truncate rounded-md bg-emphasis px-2 py-1 text-xs text-primary">{{ event.titleKey ? $t(event.titleKey) : event.title }}</span></button></div></section><section class="workspace-panel"><div class="panel-heading"><h2>{{ $t('calendar.upcoming') }}</h2></div><div v-for="item in upcoming" :key="item.id" class="flex gap-3 border-b border-surface py-4 last:border-0"><span class="mt-1 size-2 rounded-full" :style="{background:item.color}" /><div><strong class="block text-sm font-medium">{{ item.titleKey ? $t(item.titleKey) : item.title }}</strong><small class="text-muted-color">{{ item.isoDate }} · {{ item.time }}</small></div></div></section></div></AsyncContent><Dialog v-model:visible="dialogOpen" modal :header="$t('calendar.new')" class="w-[420px] max-w-[90vw]"><div class="grid gap-4"><label class="form-field"><span>{{ $t('calendar.eventName') }}</span><InputText v-model="eventTitle" /></label><label class="form-field"><span>{{ $t('calendar.eventDate') }}</span><DatePicker v-model="eventDate" show-time fluid /></label></div><template #footer><Button :label="$t('common.cancel')" text @click="dialogOpen=false" /><Button :label="$t('common.save')" :disabled="!eventTitle.trim() || !eventDate" @click="saveEvent" /></template></Dialog></template>
